import'dart:async';import'dart:convert';import'package:flutter_blue_plus/flutter_blue_plus.dart';import'package:usb_serial/usb_serial.dart';
class SensorReading{final String sensorId,quantity,unit;final double value;final int timestamp;SensorReading(this.sensorId,this.quantity,this.unit,this.value):timestamp=DateTime.now().millisecondsSinceEpoch;Map<String,dynamic>toJson()=>{'sensorId':sensorId,'quantity':quantity,'unit':unit,'value':value,'timestamp':timestamp};}
List<SensorReading>parseSensorLines(String text,String id)=>const LineSplitter().convert(text).where((x)=>x.trim().isNotEmpty).map((line){final p=line.split(',');if(p.length<3)throw FormatException('Expected quantity,unit,value');final v=double.parse(p[2].trim());return SensorReading(id,p[0].trim(),p[1].trim(),v);}).toList();
abstract class MobileSensorAdapter{String get id;Future<void>connect();Future<List<SensorReading>>read();Future<void>disconnect();}
class UsbSerialSensorAdapter implements MobileSensorAdapter{UsbPort?port;@override String get id=>'arduino_serial';@override Future<void>connect()async{final devices=await UsbSerial.listDevices();if(devices.isEmpty)throw StateError('No USB serial device found');port=await devices.first.create();if(port==null||!await port!.open())throw StateError('Could not open USB serial device');await port!.setDTR(true);await port!.setRTS(true);port!.setPortParameters(115200,UsbPort.DATABITS_8,UsbPort.STOPBITS_1,UsbPort.PARITY_NONE);}@override Future<List<SensorReading>>read()async{final p=port;if(p==null)throw StateError('USB device not connected');final bytes=await p.inputStream!.first.timeout(const Duration(seconds:5));return parseSensorLines(utf8.decode(bytes),'usb');}@override Future<void>disconnect()async{await port?.close();port=null;}}
class BleSensorAdapter implements MobileSensorAdapter{BluetoothDevice?device;BluetoothCharacteristic?characteristic;@override String get id=>'microbit_serial';@override Future<void>connect()async{await FlutterBluePlus.startScan(timeout:const Duration(seconds:6));final results=await FlutterBluePlus.scanResults.firstWhere((x)=>x.isNotEmpty).timeout(const Duration(seconds:7));await FlutterBluePlus.stopScan();device=results.first.device;await device!.connect();final services=await device!.discoverServices();for(final s in services){for(final c in s.characteristics){if(c.properties.notify||c.properties.read){characteristic=c;if(c.properties.notify)await c.setNotifyValue(true);return;}}}throw StateError('No readable BLE characteristic found');}@override Future<List<SensorReading>>read()async{final c=characteristic;if(c==null)throw StateError('BLE sensor not connected');final bytes=c.properties.read?await c.read():await c.lastValueStream.first.timeout(const Duration(seconds:5));return parseSensorLines(utf8.decode(bytes),'ble');}@override Future<void>disconnect()async{await device?.disconnect();device=null;characteristic=null;}}